class Solution:
    def maximizeExpression(self, nums: List[int]) -> int:
        m1 = m2 = float('-inf'); mn = float('inf')
        for x in nums:
            if x > m1: m2 = m1; m1 = x
            elif x > m2: m2 = x
            mn = min(mn, x)
        return m1 + m2 - mn

