class Solution {
public:
    int maximizeExpression(vector<int>& nums) {
        long long m1 = LLONG_MIN, m2 = LLONG_MIN, mn = LLONG_MAX;
        for (int x : nums) {
            if (x > m1) { m2 = m1; m1 = x; }
            else if (x > m2) m2 = x;
            mn = min(mn, (long long)x);
        }
        return (int)(m1 + m2 - mn);
    }
};

